import numpy as np

def find_zero(xs: list):
    # Ensure that the input list has an even number of coefficients
    if len(xs) % 2 != 0:
        raise ValueError("The number of coefficients must be even.")

    # Create a polynomial using numpy's roots function
    coefficients = xs[::-1]  # Reverse the list for numpy
    roots = np.roots(coefficients)

    # Return the real root (if it exists)
    for root in roots:
        if np.isreal(root):
            return float(root)

    raise ValueError("No real root found.")

